sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (newValue === '') {

        //Clearing and hiding 1 field
        g_form.clearValue("u_member_number_dependent_number");
        g_form.setDisplay("u_member_number_dependent_number", false);
        return;
    }

    g_form.setDisplay("u_member_number_dependent_number", true);
    g_form.clearValue("u_member_number_dependent_number");

    var policySys = g_form.getValue("u_master_policy_number_audit");

    var ga = new GlideAjax('x_rptp_kotak.kotak_validations');
    ga.addParam('sysparm_name', 'getMemberSys_client');
    ga.addParam('policySys', policySys);
    ga.addParam('loanSys', newValue);
    ga.getXML(getResponse);

    function getResponse(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");

        var trimmedString = answer.replace('sys_idIN', '');
        var sysIdArray = trimmedString.split(',');

        if (sysIdArray != "") {
            var sysIdCount = sysIdArray.length;

            if (sysIdCount == 1) {
                g_form.setValue("u_member_number_dependent_number", sysIdArray);
            }
        }
    }

}
